"""Self-contained evidence explorer. No external assets or live requests."""
import html
import json


def dashboard(value):
    esc = lambda x: html.escape(str(x), quote=True)
    rows = "".join(f'<tr data-severity="{esc(d["severity"])}"><td>{esc(d["id"])}</td><td>{esc(d["name"])}</td><td>{esc(d["severity"])}</td><td>{esc(", ".join(d["techniques"]))}</td><td>Disabled</td></tr>' for d in value["detections"])
    evidence = "".join(f'<li><strong>{esc(e["class"])}</strong><br>{esc(e["path"])}<br><small>{esc(e["observed_at"])} · SHA-256 {esc(e["sha256"])}</small></li>' for e in value["actual_cloud_evidence"])
    findings = value["risk"]["findings"]
    timeline = "".join(f'<li><time>{esc(e["time"])}</time><b>{esc(e["kind"])}</b><span>{esc(e["source"])} · {esc(e["source_event_id"])}</span></li>' for f in findings for e in f["evidence_chain"])
    safe_json = json.dumps(value, ensure_ascii=True, allow_nan=False).replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
    acceptance = "Local lab and live scheduled incident verified" if value["real_scheduled_lifecycle_verified"] else "Local lab verified; live incident acceptance pending"
    return '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>SentinelOps MXDR · Engineering evidence lab</title><style>
:root{color-scheme:dark;--bg:#09101d;--panel:#111e30;--ink:#e7effb;--muted:#a4b4ca;--accent:#62e3c4;--line:#2b405b;--gold:#f2c76e}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 system-ui,sans-serif}main{max-width:1240px;margin:auto;padding:36px 24px}header{padding:24px 0 36px}h1{font-size:clamp(2rem,5vw,3.8rem);line-height:1.1;letter-spacing:-.04em;margin:12px 0}h2{font-size:1.5rem;margin-top:36px}h3{margin:0 0 8px}small,.muted{color:var(--muted)}.eyebrow{color:var(--accent);letter-spacing:.16em;font-size:.75rem;text-transform:uppercase}.notice{border-left:3px solid var(--gold);padding:14px 18px;background:#1f2330;max-width:950px}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px;margin:28px 0}.card,section.panel{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:22px}.metric{font-size:2.1rem;font-weight:750;color:var(--accent)}.card p{margin:0}nav{display:flex;flex-wrap:wrap;gap:10px}button,a.button,select{background:#183047;color:var(--ink);padding:9px 14px;border:1px solid #3c5a79;border-radius:6px;font:inherit;cursor:pointer}button[aria-selected=true]{border-color:var(--accent);color:var(--accent)}a{color:var(--accent)}[hidden]{display:none!important}.diagram{display:flex;flex-wrap:wrap;align-items:center;gap:10px;padding:24px 0}.node{padding:12px;border:1px solid var(--line);border-radius:8px}.arrow{color:var(--accent)}table{width:100%;border-collapse:collapse;font-size:.9rem;margin:18px 0}th,td{padding:12px;text-align:left;border-bottom:1px solid var(--line)}th{color:var(--accent)}.scroll{overflow-x:auto}.timeline{list-style:none;padding:0}.timeline li{padding:12px 16px;border-left:2px solid var(--accent);margin-left:8px}.timeline time{display:block;color:var(--muted);font-size:.8rem}.timeline b{display:block}.timeline span{font-size:.8rem;overflow-wrap:anywhere;color:var(--muted)}.evidence{padding-left:20px}.evidence li{padding:14px 0;overflow-wrap:anywhere}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:.85rem}.tag{color:var(--gold)}footer{border-top:1px solid var(--line);margin-top:40px;padding-top:18px;font-size:.85rem;color:var(--muted)}:focus-visible{outline:3px solid var(--gold);outline-offset:3px}@media(max-width:600px){main{padding:22px 14px}th,td{padding:8px}.card,section.panel{padding:16px}}
</style><main><header><div class="eyebrow">Detection engineering / platform operations / controlled automation</div><h1>SentinelOps MXDR</h1><p class="muted">An evidence-led engineering lab for the fictional Atlas Financial customer.</p><p class="notice">This is a local synthetic replay, not a live SOC dashboard. Historical Azure evidence is listed separately. Twelve managed detections are disabled and the owned AMA machine is stopped.</p></header>
<div class="metrics"><div class="card"><div class="metric">12</div><p>Versioned Azure detections</p><small>Deployed disabled</small></div><div class="card"><div class="metric">''' + esc(value["health"]["faults_passed"]) + '''</div><p>Health faults checked</p><small>Safe local simulations</small></div><div class="card"><div class="metric">1</div><p>Correlated case closed</p><small>Synthetic, reviewer-gated</small></div><div class="card"><div class="metric">10 / 10</div><p>AMA messages reconciled</p><small>Historical actual Kusto evidence</small></div></div>
<nav role="tablist" aria-label="Evidence views"><button role="tab" data-tab="tour" aria-selected="true">Engineering tour</button><button role="tab" data-tab="catalog" aria-selected="false">Detection catalog</button><button role="tab" data-tab="case" aria-selected="false">Case timeline</button><button role="tab" data-tab="cloud" aria-selected="false">Actual cloud evidence</button></nav>
<section id="tour" class="panel" role="tabpanel"><h2>From telemetry to an auditable decision</h2><div class="diagram"><span class="node">Normalize</span><span class="arrow">→</span><span class="node">Correlate</span><span class="arrow">→</span><span class="node">Investigate</span><span class="arrow">→</span><span class="node">Review</span><span class="arrow">→</span><span class="node">Classify</span></div><div class="grid"><article class="card"><h3>Detection and source reliability</h3><p>Sixty portfolio controls, schema validation and fault injection keep signal logic and collection uncertainty visible.</p><p><a href="health/dashboard.html">Explore source health</a></p></article><article class="card"><h3>Risk with original evidence</h3><p>Ordered events, identity joins, score decay and deduplication retain the lineage behind the finding.</p><p><a href="risk/dashboard.html">Explore risk replay</a></p></article><article class="card"><h3>SOAR with bounded authority</h3><p>Persistent cases, approval expiry, transactional audit and idempotent ticket delivery demonstrate controlled local orchestration.</p><p><a href="soar/report.synthetic.json">Inspect case and audit JSON</a></p></article></div><h3>Acceptance boundary</h3><p class="tag">''' + esc(acceptance) + '''</p><p>Local code and synthetic controls are executable. Bicep comparison is not ARM deployment. Actual scheduled-alert acceptance is accepted only when both creation and classified-closure evidence records exist.</p></section>
<section id="catalog" class="panel" role="tabpanel" hidden><h2>Detection portfolio</h2><label for="severity">Severity </label><select id="severity"><option>All</option><option>High</option><option>Medium</option><option>Low</option></select><div class="scroll"><table><thead><tr><th>ID</th><th>Signal</th><th>Severity</th><th>ATT&amp;CK</th><th>Cloud state</th></tr></thead><tbody id="rules">''' + rows + '''</tbody></table></div><p class="muted">Technique mappings describe behavior, not proven adversary intent or ATT&amp;CK coverage completeness.</p></section>
<section id="case" class="panel" role="tabpanel" hidden><h2>One synthetic investigation</h2><p>The same canonical RBA finding is passed to SOAR. All seven source-event IDs are preserved. This timeline is fictional; no authentication attack or containment was executed.</p><ol class="timeline">''' + timeline + '''</ol><button id="case-details">Show structured case summary</button><pre id="case-json" hidden></pre></section>
<section id="cloud" class="panel" role="tabpanel" hidden><h2>Actual Azure evidence</h2><p>These are committed, sanitized, point-in-time observations. This offline command does not refresh them. Digests bind the local report to the cited records.</p><ul class="evidence">''' + evidence + '''</ul></section><footer>No remote assets, cookies, analytics, live queries or recurring tasks. Full local report: <a href="report.json">report.json</a>. Source, customer handover and recovery instructions are in the accompanying repository.</footer></main>
<script type="application/json" id="lab-data">''' + safe_json + '''</script><script>
const data=JSON.parse(document.getElementById('lab-data').textContent);document.querySelectorAll('[data-tab]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-selected',String(b===button)));document.querySelectorAll('[role=tabpanel]').forEach(panel=>panel.hidden=panel.id!==button.dataset.tab)}));document.getElementById('severity').addEventListener('change',function(){document.querySelectorAll('#rules tr').forEach(row=>row.hidden=this.value!=='All'&&row.dataset.severity!==this.value)});document.getElementById('case-details').addEventListener('click',()=>{const p=document.getElementById('case-json');p.hidden=!p.hidden;p.textContent=JSON.stringify(data.soar,null,2)});
</script></html>'''
